import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './catalogo.css';
import './catalogoResponsive.css';

const productos = [
  {
    id: 1,
    nombre: 'Collar de Plata Artesanal',
    categoria: 'Joyería',
    precio: 45000,
    artesano: 'María González',
  },
  {
    id: 2,
    nombre: 'Vasija de Barro Tradicional',
    categoria: 'Cerámica',
    precio: 32000,
    artesano: 'Carlos Mendoza',
  },
  {
    id: 3,
    nombre: 'Ruana de Lana Pura',
    categoria: 'Textiles',
    precio: 85000,
    artesano: 'Ana Rodríguez',
  },
  {
    id: 4,
    nombre: 'Cuadro en Madera Tallada',
    categoria: 'Madera',
    precio: 47000,
    artesano: 'Juan Pérez',
  },
  {
    id: 5,
    nombre: 'Bolso de Cuero Hecho a Mano',
    categoria: 'Cuero',
    precio: 62000,
    artesano: 'Luisa Ríos',
  },
  {
    id: 6,
    nombre: 'Pulsera de Metal Repujado',
    categoria: 'Metal',
    precio: 38000,
    artesano: 'Pedro Gómez',
  },
  {
    id: 7,
    nombre: 'Escultura de Piedra Volcánica',
    categoria: 'Piedra',
    precio: 91000,
    artesano: 'Andrea Silva',
  },
  {
    id: 8,
    nombre: 'Florero de Vidrio Reciclado',
    categoria: 'Vidrio',
    precio: 29000,
    artesano: 'Camilo Ortiz',
  },
  {
    id: 9,
    nombre: 'Cuaderno de Papel Artesanal',
    categoria: 'Papel',
    precio: 15000,
    artesano: 'Valentina Mejía',
  },
];

const CatalogoProductos = () => {
  const [mostrarFiltros, setMostrarFiltros] = useState(false);

  return (
    <div className="catalogo-wrapper">
      {/* Botón visible solo en móviles */}
      <button
        className="btn-toggle-filtros"
        onClick={() => setMostrarFiltros(!mostrarFiltros)}
      >
        {mostrarFiltros ? 'Ocultar Filtros' : 'Mostrar Filtros'}
      </button>

      <aside className={`catalogo-sidebar ${mostrarFiltros ? 'mostrar' : ''}`}>
        <h2 className="sidebar-titulo">Filtros</h2>

        <div className="sidebar-seccion">
          <h3>Categoría</h3>
          {[
            'Joyería', 'Cerámica', 'Textiles', 'Madera', 'Cuero',
            'Metal', 'Vidrio', 'Papel', 'Piedra', 'Otros'
          ].map((cat, idx) => (
            <label key={idx} className="checkbox-item">
              <input type="checkbox" /> {cat}
            </label>
          ))}
        </div>

        <div className="sidebar-seccion">
          <h3>Rango de Precio</h3>
          <label className="checkbox-item"><input type="checkbox" /> Menos de $30.000</label>
          <label className="checkbox-item"><input type="checkbox" /> $30.000 - $50.000</label>
          <label className="checkbox-item"><input type="checkbox" /> $50.000 - $80.000</label>
          <label className="checkbox-item"><input type="checkbox" /> Más de $80.000</label>
        </div>

        <button className="btn-aplicar">Aplicar Filtros</button>
      </aside>

      <main className="catalogo-contenido">
        <h1 className="catalogo-titulo">Catálogo de Productos ({productos.length} productos)</h1>

        <div className="catalogo-grid">
          {productos.map(producto => (
            <div key={producto.id} className="producto">
              <div className="producto-imagen" />
              <div className="producto-info">
                <span className="producto-categoria">{producto.categoria}</span>
                <h3 className="producto-nombre">{producto.nombre}</h3>
                <p className="producto-artesano">Por: {producto.artesano}</p>
                <p className="producto-precio">${producto.precio.toLocaleString()}</p>
                <button className="btn-ver">Ver Más</button>
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
};

export default CatalogoProductos;
